const AuthSchema = z
  .object({
    access_token: z
      .string()
      .openapi({
        description: 'The access token string.',
        example: '01019a4a62aec63db077317ab7bb429db75652401e',
      }),
    app: ApiAppSchema.openapi({ description: 'The API application associated with the token.' }),
    expires_on: z
      .string()
      .exactOptional()
      .openapi({ description: 'The date and time that the token expires.', example: '1495048954' }),
    refresh_token: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The refresh token string.',
        example: '3d3bc8a9cb7debfd01b270e419b2d265983362f9',
      }),
    scope: z
      .string()
      .openapi({
        description: 'The scope or scopes that the token supports.',
        example: 'private create edit upload public',
      }),
    token_type: z
      .literal('bearer')
      .openapi({
        description:
          'The token type:\n\nOption descriptions:\n * `bearer` - The token is of the `bearer` type.\n',
        example: 'bearer',
      }),
    user: UserSchema.exactOptional().openapi({
      description: 'The user associated with the token.',
    }),
  })
  .openapi({ required: ['access_token', 'app', 'scope', 'token_type'], title: 'Auth' })
  .openapi('Auth')

const AuthErrorSchema = z
  .object({
    error: z.string().openapi({ description: 'The name of the error.', example: 'server_error' }),
    error_description: z
      .string()
      .openapi({
        description: 'The description of the error.',
        example: "An error has occurred on Vimeo's servers. Please try again.",
      }),
  })
  .openapi({ required: ['error', 'error_description'], title: 'Auth Error' })
  .openapi('AuthError')

const CommentSchema = z
  .object({
    created_on: z
      .string()
      .openapi({
        description: 'The time in ISO 8601 format when the comment was posted.',
        example: '2018-03-05T21:04:47+00:00',
      }),
    metadata: z
      .object({
        connections: z
          .object({
            replies: z
              .object({
                options: z
                  .array(z.string())
                  .openapi({ description: 'An array of HTTP methods permitted on this URI.' }),
                total: z
                  .number()
                  .openapi({
                    description: 'The total number of replies on this connection.',
                    example: 42,
                  }),
                uri: z
                  .string()
                  .openapi({
                    description: 'The API URI that resolves to the connection data.',
                    example: '/videos/258684937/comments/12345/replies',
                  }),
              })
              .openapi({
                description: "Information about this comment's replies.",
                required: ['options', 'total', 'uri'],
              }),
          })
          .openapi({ required: ['replies'] }),
      })
      .openapi({ required: ['connections'] }),
    resource_key: z
      .string()
      .openapi({
        description: 'The resource key string for the comment.',
        example: 'bac1033deba2310ebba2caec33c23e4beea67aba',
      }),
    text: z
      .string()
      .openapi({ description: 'The content of the comment.', example: 'I love this!' }),
    type: z
      .literal('video')
      .openapi({
        description:
          'The Vimeo content to which the comment relates:\n\nOption descriptions:\n * `video` - The comment is about a video.\n',
        example: 'video',
      }),
    uri: z
      .string()
      .openapi({
        description: 'The unique identifier to access the comment resource.',
        example: '/videos/258684937/comments/12345',
      }),
    user: UserSchema.nullable().openapi({ description: 'The user who posted the comment.' }),
  })
  .openapi({
    required: ['created_on', 'metadata', 'resource_key', 'text', 'type', 'uri', 'user'],
    title: 'Comment',
  })
  .openapi('Comment')

const ContentRatingSchema = z
  .object({
    code: z
      .enum(['drugs', 'language', 'nudity', 'safe', 'unrated', 'violence'])
      .openapi({
        description:
          'The code that uniquely identifies this content rating:\n\nOption descriptions:\n * `drugs` - Drug or alcohol use.\n * `language` - Profanity or sexually suggestive content.\n * `nudity` - Nudity.\n * `safe` - Suitable for all audiences.\n * `unrated` - No rating.\n * `violence` - Violent or graphic content.\n',
        example: 'violence',
      }),
    name: z
      .string()
      .openapi({ description: 'The description of this content rating.', example: 'Violence' }),
    uri: z
      .string()
      .nullable()
      .openapi({
        description: 'The canonical relative URI of the content rating.',
        example: '/contentrating/violence',
      }),
  })
  .openapi({ required: ['code', 'name', 'uri'], title: 'Content Rating' })
  .openapi('ContentRating')

const CreativeCommonsSchema = z
  .object({
    code: z
      .enum(['by', 'by-nc', 'by-nc-nd', 'by-nc-sa', 'by-nd', 'by-sa', 'cc0'])
      .openapi({
        description:
          'The code that uniquely identifies this Creative Commons license:\n\nOption descriptions:\n * `by` - Attribution\n * `by-nc` - Attribution Non-Commercial\n * `by-nc-nd` - Attribution Non-Commercial No Derivatives\n * `by-nc-sa` - Attribution Non-Commercial Share Alike\n * `by-nd` - Attribution No Derivatives\n * `by-sa` - Attribution Share Alike\n * `cc0` - Public Domain Dedication\n',
        example: 'by-sa',
      }),
    name: z
      .string()
      .openapi({
        description: 'The description of this Creative Commons license.',
        example: 'Attribution Share Alike',
      }),
    uri: z
      .string()
      .nullable()
      .openapi({
        description: 'The canonical relative URI of the Creative Commons license.',
        example: '/creativecommons/by-sa',
      }),
  })
  .openapi({ required: ['code', 'name', 'uri'], title: 'Creative Commons' })
  .openapi('CreativeCommons')

const CreditSchema = z
