const VideoVersionsSchema = z
  .object({
    active: z
      .boolean()
      .openapi({
        description: 'Whether this video version is the currently active one.',
        example: 'true',
      }),
    app: ApiAppSchema.openapi({ description: 'The API app associated with the video version.' }),
    created_time: z
      .string()
      .openapi({
        description: 'The time in ISO 8601 for when the video version was created.',
        example: '2018-03-05T21:04:47+00:00',
      }),
    duration: z
      .number()
      .nullable()
      .openapi({ description: 'The duration of the video version in seconds.', example: 81 }),
    filename: z
      .string()
      .openapi({ description: 'The file name of the video version.', example: 'rev2.mp4' }),
    filesize: z
      .number()
      .nullable()
      .openapi({ description: 'The size in byes of the video version file.', example: 4025322521 }),
    metadata: z
      .object({
        connections: z
          .object({
            video: z
              .object({
                options: z
                  .array(z.string())
                  .openapi({ description: 'An array of HTTP methods permitted on this URI.' }),
                total: z
                  .number()
                  .openapi({
                    description: 'The total number of videos on this connection.',
                    example: 5,
                  }),
                uri: z
                  .string()
                  .openapi({
                    description: 'The API URI that resolves to the connection data.',
                    example: '/videos/258684937',
                  }),
              })
              .openapi({
                description: 'Data from video associated with version',
                required: ['options', 'total', 'uri'],
              }),
          })
          .openapi({ required: ['video'] }),
      })
      .openapi({ description: "The video version's metadata.", required: ['connections'] }),
    modified_time: z
      .string()
      .openapi({
        description: 'The time in ISO 8601 format when the video version was last modified.',
        example: '2018-09-16T09:02:40+00:00',
      }),
    play: PlaySchema.openapi({ description: 'The Play representation.' }),
    upload: z
      .object({
        approach: z
          .enum(['post', 'pull', 'streaming', 'tus'])
          .exactOptional()
          .openapi({ description: 'The approach for uploading the video.', example: 'post' }),
        complete_uri: z
          .string()
          .exactOptional()
          .openapi({ description: 'The URI for completing the upload.' }),
        form: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The HTML form for uploading a video through the post approach.',
          }),
        link: z
          .string()
          .exactOptional()
          .openapi({ description: 'The link of the video to capture through the pull approach.' }),
        redirect_url: z
          .string()
          .exactOptional()
          .openapi({ description: 'The redirect URL for the upload app.' }),
        size: z
          .number()
          .exactOptional()
          .openapi({
            description: 'The file size in bytes of the uploaded video.',
            example: 60000,
          }),
        status: z
          .enum(['complete', 'error', 'in_progress'])
          .openapi({
            description:
              'The status code for the availability of the uploaded video:\n\nOption descriptions:\n * `complete` - The upload is complete.\n * `error` - The upload ended with an error.\n * `in_progress` - The upload is underway.\n',
            example: 'complete',
          }),
        upload_link: z
          .string()
          .exactOptional()
          .openapi({ description: 'The link for sending video file data.' }),
      })
      .nullable()
      .openapi({ description: 'The upload information for this version.', required: ['status'] }),
    upload_date: z
      .string()
      .nullable()
      .openapi({
        description: 'The time in ISO 8601 format when the video version was uploaded.',
        example: '2018-09-16T09:02:40+00:00',
      }),
    uri: z
      .string()
      .openapi({
        description: "The version's canonical relative URI.",
        example: '/videos/258684937/versions/12345',
      }),
    user: UserSchema.nullable().openapi({ description: 'The owner of the video version.' }),
  })
  .openapi({
    required: [
      'active',
      'app',
      'created_time',
      'duration',
      'filename',
      'filesize',
      'metadata',
      'modified_time',
      'play',
      'upload',
      'upload_date',
      'uri',
      'user',
    ],
    title: 'Video Versions',
  })
  .openapi('VideoVersions')

