export const getCategoriesRoute = createRoute({
  method: 'get',
  path: '/categories',
  tags: ['Categories\\Essentials'],
  summary: 'Get all categories',
  description: 'This method gets all existing categories.',
  operationId: 'get_categories',
  request: {
    query: z.object({
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description: 'The sort direction of the results.',
            in: 'query',
            name: 'direction',
            required: false,
            schema: { enum: ['asc', 'desc'], example: 'asc', type: 'string' },
          },
          example: 'asc',
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The page number of the results to show.',
            in: 'query',
            name: 'page',
            required: false,
            schema: { example: 1, type: 'number' },
          },
          example: 1,
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The number of items to show on each page of results, up to a maximum of 100.',
            in: 'query',
            name: 'per_page',
            required: false,
            schema: { example: 10, type: 'number' },
          },
          example: 10,
        }),
      sort: z
        .enum(['last_video_featured_time', 'name'])
        .exactOptional()
        .openapi({
          param: {
            description: 'The way to sort the results.',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { enum: ['last_video_featured_time', 'name'], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The categories were returned.',
      content: { 'application/vnd.vimeo.category+json': { schema: z.array(CategorySchema) } },
    },
  },
})

