export const postMeFollowingRoute = createRoute({
  method: 'post',
  path: '/me/following',
  tags: ['Users\\Follows'],
  summary: 'Follow a list of users',
  operationId: 'follow_users_alt1',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              users: z
                .array(z.string())
                .openapi({ description: 'An array of user URIs for the list of users to follow.' }),
            })
            .openapi({ required: ['users'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'The users were followed.' },
    400: {
      description:
        "* Error code 2205: The request body is empty.\n* Error code 2205: The `users` array is invalid.\n* Error code 2205: The list of users doesn't contain URIs.\n* Error code 2900: A user in the list doesn't exist.\n* Error code 2901: The list contains more than 100 users.",
      content: { 'application/json': { schema: ErrorSchema } },
    },
    401: {
      description: 'Error code 8000: The user access token is invalid.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    403: {
      description: "Error code 3417: The current user can't follow other users.",
      content: { 'application/json': { schema: ErrorSchema } },
    },
    429: {
      description: 'Error code 9006: The current user is rate-limited from following other users.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    500: {
      description: 'Error code 4005: An unexpected error occurred.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['interact'] }],
})

