export const postOndemandPagesOndemandIdPromotionsRoute = createRoute({
  method: 'post',
  path: '/ondemand/pages/{ondemand_id}/promotions',
  tags: ['On Demand\\Promotions'],
  summary: 'Add a promotion to an On Demand page',
  operationId: 'create_vod_promotion',
  request: {
    params: z.object({
      ondemand_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: {
            description: 'The ID of the On Demand.',
            in: 'path',
            name: 'ondemand_id',
            required: true,
            schema: { example: 61326, type: 'number' },
          },
          example: 61326,
        }),
    }),
    body: {
      content: {
        'application/vnd.vimeo.ondemand.promotion+json': {
          schema: z
            .object({
              access_type: z
                .enum(['default', 'vip'])
                .exactOptional()
                .openapi({
                  description:
                    'The promotion access type, which is a purchase option that isn\'t available on the container. VIP promotions always make the content free of charge. If you use this type, you must further define the promotion with the `download` or `stream_period` fields.\n\nOption descriptions:\n * `default` - Promotions grant discount on the existing purchase options for an On Demand Container.\n * `vip` - Promotions can be used to grant free access to VOD content before it is released, or to offer a purchase option that isn\'t available on the container. "vip" promotions will always make the content free, and must be further defined with the `download` or `stream_period` fields.\n',
                }),
              code: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The promotion code. This field is ignored for batch promotions.',
                  example: 'sxsw2018',
                }),
              discount_type: z
                .enum(['free', 'percent'])
                .exactOptional()
                .openapi({
                  description:
                    'The type of discount offered by the promo code. When `access_type` is `vip`, the value of this field must be `free`.\n\nOption descriptions:\n * `free` - Reduces the price to zero.\n * `percent` - Reduces the price by an amount defined in the "percent_off" field.\n',
                }),
              download: z
                .boolean()
                .openapi({
                  description:
                    'Whether the promotion grants download access to VOD content. This is necessary only when not previously defined in the On Demand container or when `access_type` is `vip` or `product_type` is `buy`.',
                  example: 'true',
                }),
              end_time: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The end of the promotion period. If you don't specify a value, the promotion will never expire.",
                  example: '1526089920',
                }),
              label: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The description of a batch promotion. This field is ignored for single promotions.',
                  example: 'sxsw',
                }),
              percent_off: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'The percentage of the discount by using this promo code. This field is applicable only when `discount_type` is `percent`.',
                  example: 50,
                }),
              product_type: z
                .enum(['any', 'buy', 'buy_episode', 'rent', 'rent_episode', 'subscribe'])
                .exactOptional()
                .openapi({
                  description:
                    'The type of transaction to which the promotion applies. When `access_type` is `default`, the default value is `any`, but the default value is `rent` when `access_type` is `vip`. Also, when `access_type` is `vip`, the only valid product types are `buy` and `rent`.',
                }),
              start_time: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The start of the promotion period. If you don't specify a value, the start time defaults to the time that the promotion was created.",
                  example: '1526089920',
                }),
              stream_period: z
                .enum([
                  '1_week',
                  '1_year',
                  '24_hour',
                  '30_day',
                  '3_month',
                  '48_hour',
                  '6_month',
                  '72_hour',
                ])
                .openapi({
                  description:
                    'The amount of time that a user has access to the VOD content upon redeeming a promo code. This field is necessary only when not defined in the On Demand container or when creating promotions when `access_type` is `vip` or `product_type` is `rent`.',
                }),
              total: z
                .number()
                .openapi({
                  description:
                    'The number of promotions to generate when `type` is `batch`, or the number of uses of the promotion when `type` is `single`.',
                  example: 9,
                }),
              type: z
                .enum(['batch', 'single'])
                .openapi({
                  description:
                    'The type of promotion. When `access_type` is `vip`, the value for this field must be `batch`.\n\nOption descriptions:\n * `batch` - Generates many random promo codes with one use each.\n * `single` - Generates one promo code that can be used many times.\n',
                }),
            })
            .openapi({ required: ['download', 'stream_period', 'total', 'type'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The promotion was added.',
      content: {
        'application/vnd.vimeo.ondemand.promotion+json': { schema: OnDemandPromotionSchema },
      },
    },
    400: {
      description: '* There are errors in the request.\n* The promo code already exists.',
      content: { 'application/vnd.vimeo.ondemand.promotion+json': { schema: LegacyErrorSchema } },
    },
    403: {
      description: "You can't create promotions for an On Demand page that you don't own.",
      content: { 'application/vnd.vimeo.ondemand.promotion+json': { schema: LegacyErrorSchema } },
    },
    404: {
      description: 'No such On Demand page exists.',
      content: { 'application/vnd.vimeo.ondemand.promotion+json': { schema: LegacyErrorSchema } },
    },
  },
  security: [{ oauth2: ['promo_codes', 'create'] }],
})

